// ===== PARSE SCENE PROMPTS FROM GEMINI =====

const geminiResponse = $input.first().json;
let rawText;

if (geminiResponse.content?.parts?.[0]?.text) {
  rawText = geminiResponse.content.parts[0].text;
} else if (geminiResponse.text) {
  rawText = geminiResponse.text;
} else if (typeof geminiResponse === 'string') {
  rawText = geminiResponse;
} else {
  throw new Error('❌ Cannot find scene prompts in Gemini response');
}

// Remove markdown fences
let cleanedText = rawText;
if (rawText.includes('```json')) {
  const jsonMatch = rawText.match(/```json\s*([\s\S]*?)\s*```/);
  if (jsonMatch && jsonMatch[1]) {
    cleanedText = jsonMatch[1];
  }
} else if (rawText.includes('```')) {
  const jsonMatch = rawText.match(/```\s*([\s\S]*?)\s*```/);
  if (jsonMatch && jsonMatch[1]) {
    cleanedText = jsonMatch[1];
  }
}

// Parse JSON
let sceneData;
try {
  sceneData = JSON.parse(cleanedText);
} catch (e) {
  console.error('❌ JSON Parse Error:', e.message);
  console.error('Content:', cleanedText.substring(0, 500));
  throw new Error('Failed to parse scene prompts JSON: ' + e.message);
}

// Validate
if (!sceneData.scenes || !Array.isArray(sceneData.scenes)) {
  throw new Error('❌ Invalid scene data: missing scenes array');
}

if (sceneData.scenes.length === 0) {
  throw new Error('❌ No scenes generated');
}

console.log('✅ Scene Prompts Parsed Successfully:');
console.log('   Total Scenes:', sceneData.scenes.length);
sceneData.scenes.forEach(scene => {
  console.log(`   Scene ${scene.sceneNumber} (${scene.type}): ${scene.duration}s - ${scene.productVisible ? 'WITH' : 'NO'} product`);
});

const previousData = $('Video Requirements Calculator').first().json;

return [{
  json: {
    scenes: sceneData.scenes,
    characterReference: sceneData.characterReference,
    productIntegration: sceneData.productIntegration,
    fullVideoScript: sceneData.fullVideoScript,
    generationMetadata: sceneData.generationMetadata,
    videoConfig: previousData.videoConfig,
    productImages: previousData.productImages,
    characterImageUrl: previousData.characterImageUrl,
    timestamp: new Date().toISOString(),
    status: 'scene_prompts_ready',
    progress: 60,
    nextStep: 'scene_image_generation'
  }
}];

// ===== LOOP PREPARATION: Split scenes into individual items =====

const sceneData = $input.first().json;
const scenes = sceneData.scenes;

// Convert array of scenes into individual items for Loop node
const output = scenes.map(scene => {
  return {
    json: {
      currentScene: scene,
      characterReference: sceneData.characterReference,
      productIntegration: sceneData.productIntegration,
      videoConfig: sceneData.videoConfig,
      productImages: sceneData.productImages,
      nanoBananaConfig: {
        model: 'nano-banana-pro',
        aspectRatio: scene.technicalSpecs.aspectRatio,
        resolution: '2K',
        outputFormat: 'png'
      },
      totalScenes: scenes.length,
      timestamp: new Date().toISOString()
    }
  };
});

console.log('✅ Prepared', output.length, 'scenes for loop');

return output;

// ===== EXTRACT SCENE IMAGE URL =====

const kieResponse = $json;
const sceneContext = $('Split Scenes').item.json;

if (kieResponse.data.state !== 'success') {
  throw new Error('Scene image generation failed');
}

const resultJson = JSON.parse(kieResponse.data.resultJson);
const sceneImageUrl = resultJson.resultUrls[0];

if (!sceneImageUrl) {
  throw new Error('No image URL in response');
}

const scene = sceneContext.currentScene;

console.log('✅ Scene', scene.sceneNumber, 'image generated:', sceneImageUrl);

return [{
  json: {
    sceneNumber: scene.sceneNumber,
    sceneType: scene.type,
    duration: scene.duration,
    startTime: scene.startTime,
    endTime: scene.endTime,
    productVisible: scene.productVisible,
    imageUrl: sceneImageUrl,
    script: scene.script,
    technicalSpecs: scene.technicalSpecs,
    taskId: kieResponse.data.taskId,
    generationTime: kieResponse.data.costTime,
    timestamp: new Date().toISOString(),
    status: 'scene_image_ready'
  }
}];

// ===== COMPILE ALL SCENE IMAGES & SCRIPTS =====

const allScenes = $input.all().map(item => item.json);

// Sort by scene number
allScenes.sort((a, b) => a.sceneNumber - b.sceneNumber);

console.log('✅ All Scene Images Generated:');
allScenes.forEach(scene => {
  console.log(`   Scene ${scene.sceneNumber} (${scene.sceneType}): ${scene.imageUrl}`);
});

// Compile full script
const fullScript = allScenes.map(scene => {
  return {
    sceneNumber: scene.sceneNumber,
    timestamp: `${scene.startTime}s - ${scene.endTime}s`,
    type: scene.sceneType,
    narration: scene.script,
    duration: scene.duration
  };
});

// Prepare for video generation
const videoGenerationQueue = allScenes.map(scene => {
  return {
    sceneNumber: scene.sceneNumber,
    imageUrl: scene.imageUrl,
    duration: scene.duration,
    script: scene.script,
    technicalSpecs: scene.technicalSpecs
  };
});

return [{
  json: {
    sceneImages: allScenes,
    fullScript,
    videoGenerationQueue,
    summary: {
      totalScenes: allScenes.length,
      totalDuration: allScenes.reduce((sum, s) => sum + s.duration, 0),
      allImagesGenerated: allScenes.every(s => s.imageUrl),
      readyForVideoGeneration: true
    },
    timestamp: new Date().toISOString(),
    status: 'all_scene_images_ready',
    progress: 80,
    nextStep: 'video_generation_per_scene'
  }
}];

// ===== VIDEO GENERATION PLACEHOLDER =====
// TODO: Implement video generation using seedance-1-5-pro or veo3.1

